text:
Caveman mode: **full**.

---

```tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    // Swap for Sentry/Datadog in prod
    console.error("[ErrorBoundary]", {
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
      timestamp: new Date().toISOString(),
    });

    this.props.onError?.(error, info);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.reset);

    return <DefaultFallback error={error} reset={this.reset} />;
  }
}

// ── Default fallback UI ──────────────────────────────────────────────────────

function DefaultFallback({ error, reset }: { error: Error; reset: () => void }) {
  return (
    <div role="alert" style={styles.container}>
      <span style={styles.icon}>⚠️</span>
      <h2 style={styles.title}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={reset} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles = {
  container: {
    display: "flex",
    flexDirection: "column" as const,
    alignItems: "center",
    gap: "12px",
    padding: "32px",
    borderRadius: "8px",
    border: "1px solid #f87171",
    background: "#fff1f1",
    fontFamily: "sans-serif",
    maxWidth: "480px",
    margin: "40px auto",
  },
  icon:    { fontSize: "2rem" },
  title:   { margin: 0, color: "#b91c1c", fontSize: "1.2rem" },
  message: {
    margin: 0,
    padding: "8px 12px",
    borderRadius: "4px",
    background: "#fee2e2",
    color: "#7f1d1d",
    fontSize: "0.85rem",
    whiteSpace: "pre-wrap" as const,
    wordBreak: "break-word" as const,
    width: "100%",
  },
  button: {
    padding: "8px 20px",
    borderRadius: "6px",
    border: "none",
    background: "#dc2626",
    color: "#fff",
    cursor: "pointer",
    fontWeight: 600,
  },
} as const;

export default ErrorBoundary;
```

---

**Usage — default fallback:**
```tsx
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>
```

**Custom fallback:**
```tsx
<ErrorBoundary
  fallback={(err, reset) => (
    <div>
      <p>Crashed: {err.message}</p>
      <button onClick={reset}>Retry</button>
    </div>
  )}
  onError={(err, info) => Sentry.captureException(err, { extra: info })}
>
  <MyComponent />
</ErrorBoundary>
```

---

**Key pieces:**

| Hook | Job |
|---|---|
| `getDerivedStateFromError` | Catch error, trigger fallback render |
| `componentDidCatch` | Side effects — log, report to service |
| `reset()` | Clear error state → retry render |

**Gotcha:** boundary not catch errors in: event handlers, async code, SSR, itself. For async, add `window.onerror` or `try/catch` + manual `setState({ error })`.
